import { DomainError } from "./DomainError";
import { OrderLine } from "./OrderLine";
import { OrderState, OrderStatus, nextState } from "./OrderState";

export class Order {
  private currentStatus: OrderStatus = "placed";

  constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
  ) {
    if (lines.length === 0) throw new DomainError("invalid", "Order needs at least one line");
  }

  get status(): OrderStatus {
    return this.currentStatus;
  }

  advance(): OrderState {
    if (this.currentStatus === "cancelled") {
      throw new DomainError("conflict", "Order is cancelled");
    }
    const next = nextState(this.currentStatus);
    if (!next) throw new DomainError("conflict", "Order is already delivered");
    this.currentStatus = next;
    return next;
  }

  cancel(): void {
    if (this.currentStatus !== "placed" && this.currentStatus !== "paid" && this.currentStatus !== "packed") {
      throw new DomainError("conflict", `Order cannot be cancelled when ${this.currentStatus}`);
    }
    this.currentStatus = "cancelled";
  }
}

