import { DomainError } from "./DomainError";

export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered"] as const;

export type OrderState = (typeof ORDER_STATES)[number];

export type OrderStatus = OrderState | "cancelled";

export function isOrderStatus(value: unknown): value is OrderStatus {
  return value === "cancelled" || (ORDER_STATES as readonly unknown[]).includes(value);
}

export function nextState(state: OrderState): OrderState | undefined {
  return ORDER_STATES[ORDER_STATES.indexOf(state) + 1];
}

export function assertOrderStatus(status: unknown): asserts status is OrderStatus {
  if (!isOrderStatus(status)) throw new DomainError("invalid", "Unknown order state");
}

