import { DomainError } from "./DomainError";
import { OrderLine } from "./OrderLine";
import { Product } from "./Product";
import { ProductRepository } from "./ProductRepository";

export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  /** Reserves all lines or none: on failure any partial reservation is rolled back. */
  async reserve(lines: readonly OrderLine[]): Promise<void> {
    const reserved: OrderLine[] = [];
    try {
      for (const line of lines) {
        const product = await this.require(line.productId);
        product.reserve(line.quantity);
        await this.products.save(product);
        reserved.push(line);
      }
    } catch (error) {
      await this.release(reserved);
      throw error;
    }
  }

  async release(lines: readonly OrderLine[]): Promise<void> {
    for (const line of lines) {
      const product = await this.require(line.productId);
      product.release(line.quantity);
      await this.products.save(product);
    }
  }

  private async require(productId: string): Promise<Product> {
    const product = await this.products.findById(productId);
    if (!product) throw new DomainError("not_found", `Product ${productId} not found`);
    return product;
  }
}

